// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public int sumNumbers(TreeNode root) {
    return dfs(root, 0);
}

private int dfs(TreeNode node, int current) {
    if (node == null) return 0;                       // no path → contributes nothing
    current = current * 10 + node.val;                // append this digit
    if (node.left == null && node.right == null) {    // leaf: number complete
        return current;
    }
    return dfs(node.left, current) + dfs(node.right, current);  // sum ALL paths
}

