# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sumNumbers(self, root: TreeNode) -> int:
    def dfs(node: TreeNode, current: int) -> int:
        if node is None:                               # no path → contributes nothing
            return 0
        current = current * 10 + node.val              # append this digit
        if node.left is None and node.right is None:   # leaf: number complete
            return current
        return dfs(node.left, current) + dfs(node.right, current)  # sum ALL paths

    return dfs(root, 0)

